/* Local currency prices are never converted or inferred. */
(()=>{'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let region='CA',feed={offers:[]},shopParts=[],limit=24;
try{region=new URLSearchParams(location.search).get('region')||localStorage.getItem('pcp-region')||'CA'}catch{}
if(!['CA','US'].includes(region))region='CA';
const currency=()=>region==='CA'?'CAD':'USD';
const money=n=>new Intl.NumberFormat(region==='CA'?'en-CA':'en-US',{style:'currency',currency:currency(),currencyDisplay:'code'}).format(n);
function offers(id){return feed.offers.filter(o=>o.id===id&&o.region===region&&o.currency===currency()&&Number.isFinite(o.price)&&o.price>0&&Date.now()-Date.parse(o.checkedAt)>=0&&Date.now()-Date.parse(o.checkedAt)<86400000).sort((a,b)=>a.price-b.price)}
function stores(p){const q=encodeURIComponent(p.brand+' '+p.name);return region==='CA'?[['Newegg Canada','https://www.newegg.ca/p/pl?d='+q],['Best Buy Canada','https://www.bestbuy.ca/en-ca/search?search='+q],['Amazon Canada','https://www.amazon.ca/s?k='+q]]:[['Newegg','https://www.newegg.com/p/pl?d='+q],['Best Buy','https://www.bestbuy.com/site/searchpage.jsp?st='+q],['Amazon','https://www.amazon.com/s?k='+q]]}
function links(p){return stores(p).map(([name,url])=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer" aria-label="Search ${esc(name)} for ${esc(p.name)}">${name} <span aria-hidden="true">↗</span></a>`).join('')}
function offerRows(p){const found=offers(p.id);return found.length?`<div class="offer-list">${found.map((o,i)=>`<a class="retailer-offer" href="${esc(o.url)}" target="_blank" rel="noopener noreferrer"><span><strong>${esc(o.store)}</strong><small>${esc(o.model)} · Checked ${new Date(o.checkedAt).toLocaleDateString('en-CA')}</small></span><span><strong>${money(o.price)}</strong><small>${found.length>1&&i===0?'Lowest checked price':'View offer'} ↗</small></span></a>`).join('')}</div>`:'<p class="price-pending">Check stores for current pricing and availability.</p>'}
function paintRegion(){document.documentElement.dataset.region=region;document.querySelectorAll('button[data-region]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.region===region)));document.querySelectorAll('[data-shopping-country]').forEach(el=>el.textContent=region==='CA'?'Canada · CAD':'United States · USD');}
function renderProduct(){const box=$('[data-product-buy]');if(!box)return;const p=JSON.parse($('#shopping-product').textContent);box.innerHTML=offerRows(p)+`<div class="store-searches"><span>Search more stores</span>${links(p)}</div>`}
function renderBuilder(){if(typeof buildInstances!=='function')return;let total=0,count=0,priced=0;
document.querySelectorAll('.builder-row[data-builder-row]').forEach(row=>{row.querySelector('.part-buying')?.remove();const instances=buildInstances(row.dataset.builderRow);if(!instances.length)return;const box=document.createElement('div');box.className='part-buying';box.innerHTML=instances.map(({part:p})=>{count++;const best=offers(p.id)[0];if(best){total+=best.price;priced++}return `<div class="build-price-line"><span>${esc(p.name)}</span>${best?`<a href="${esc(best.url)}" target="_blank" rel="noopener noreferrer"><strong>${money(best.price)}</strong><small>${esc(best.store)} ↗</small><small>${esc(best.model)}</small></a>`:`<a href="/learn/${encodeURIComponent(p.id)}.html#buy">Check stores ↗</a>`}</div>`}).join('');row.append(box)});
const summary=$('#build-shopping-summary');if(summary)summary.innerHTML=`<div class="shopping-summary-top"><div><span class="eyebrow">${priced===count&&count?'Parts subtotal':'Priced parts subtotal'}</span><h2>${priced?money(total):'—'}</h2></div><span>${region==='CA'?'Canada':'United States'}</span></div><p>${count?`${priced} of ${count} selected items have a checked price.${priced<count?` ${count-priced} still need a price.`:''}`:'Choose your first part to start a shopping list.'}</p><small>Before tax and shipping. Prices are checked snapshots, not a live quote. Verify the exact model at checkout.</small><a class="subtle-link" href="/shop/">Browse buying options →</a>`;
}
function renderShop(){const box=$('#shop-results');if(!box)return;const q=($('#shop-search').value||'').trim().toLowerCase(),cat=$('#shop-category').value;let rows=shopParts.filter(p=>(!cat||p.cat===cat)&&`${p.brand} ${p.name} ${p.summary}`.toLowerCase().includes(q));if($('#shop-priced').checked)rows=rows.filter(p=>offers(p.id).length);$('#shop-count').textContent=`${rows.length.toLocaleString()} products · ${region==='CA'?'Canada · CAD':'United States · USD'}`;
box.innerHTML=rows.slice(0,limit).map(p=>{const o=offers(p.id)[0];return `<article class="shop-card"><a class="shop-photo" href="/learn/${encodeURIComponent(p.id)}.html#buy"><img src="${esc(p.image)}" alt="${esc(p.alt)}" width="320" height="200" loading="lazy" decoding="async"></a><div class="shop-card-body"><span class="eyebrow">${esc(p.brand)}</span><h2><a href="/learn/${encodeURIComponent(p.id)}.html#buy">${esc(p.name)}</a></h2><p>${esc(p.summary)}</p><div class="shop-price">${o?`<strong>${money(o.price)}</strong><small>${esc(o.store)} · Checked price</small>`:'<span>Check store availability</span>'}</div><a class="button secondary" href="/learn/${encodeURIComponent(p.id)}.html#buy">Where to buy <span aria-hidden="true">↗</span></a></div></article>`}).join('')||'<p class="empty-message">No matches. Try another model, category, or clear the price filter.</p>';$('#shop-more').hidden=rows.length<=limit;
}
function render(){if(!document?.documentElement)return;paintRegion();renderProduct();renderBuilder();renderShop()}
document.querySelectorAll('[data-region]').forEach(b=>b.addEventListener('click',()=>{region=b.dataset.region;try{localStorage.setItem('pcp-region',region)}catch{}const url=new URL(location.href);if(url.searchParams.has('region')){url.searchParams.set('region',region);history.replaceState(null,'',url)}render()}));
document.addEventListener('pcp:build',renderBuilder);
paintRegion();renderProduct();renderBuilder();
if($('[data-product-buy],#builder,#shop-results'))fetch('/prices.json',{cache:'no-cache'}).then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{if(Array.isArray(data.offers))feed=data;render()}).catch(()=>render());
if($('#shop-results')){for(const id of ['shop-search','shop-category','shop-priced'])$('#'+id).addEventListener(id==='shop-search'?'input':'change',()=>{limit=24;renderShop()});$('#shop-more').addEventListener('click',()=>{limit+=24;renderShop()});fetch('/shopping-catalog.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{shopParts=data;renderShop()}).catch(()=>{$('#shop-results').innerHTML='<p>Shopping catalog could not load. <a href="/hardware/">Browse hardware instead →</a></p>'})}
})();
